/**
 * Upload file buffers to Rayvn /files endpoint.
 *
 * WaSOS files arrive here as binary buffers attached to each file object.
 * This node uploads each file to Rayvn and collects the returned file IDs,
 * which Rayvn requires in the log entry instead of the raw binary data.
 *
 * Pre-known failures (skipped files) have already been removed upstream
 * in POST entries — this node only processes files that have a buffer.
 *
 * On completion:
 *   - payload.files is replaced with an array of Rayvn file IDs
 *   - entry._failed_files holds any upload failures for Check for failed uploads
 */

const target     = msg.metadata.target;
const baseUrl    = global.get("parat_bridge").base_urls.rayvn;
const uploadable = (msg.payload.files || []).filter(f => f.buffer);

// Safety net: if no buffers remain, clear files and pass through
if (uploadable.length === 0) {
    msg.payload.files = [];
    return msg;
}

const resolved = [];  // Rayvn file IDs for successfully uploaded files
const failed   = [];  // files that could not be uploaded

for (const file of uploadable) {
    try {
        // Rayvn /files expects multipart/form-data — the same format a browser
        // uses for file uploads. Node-RED has no built-in helper for this,
        // so we build the multipart body manually using a boundary string
        // that separates the form fields from the binary content.
        const boundary = "----PBBoundary" + Date.now();
        const header   = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${file.name || "file.bin"}"\r\nContent-Type: ${file.type || "application/octet-stream"}\r\n\r\n`;
        const footer   = `\r\n--${boundary}--\r\n`;
        const body     = Buffer.concat([Buffer.from(header), file.buffer, Buffer.from(footer)]);

        const res = await nodeFetch(baseUrl + "/files", {
            method:  "POST",
            headers: {
                "Authorization": "Bearer " + target.api_key,
                "Content-Type":  "multipart/form-data; boundary=" + boundary
            },
            body
        });

        if (res.ok) {
            // Store the Rayvn file ID — this is what gets attached to the log entry
            const data = await res.json();
            resolved.push(data.id);
            node.log(`File uploaded: ${file.name} → ${data.id}`);
        } else {
            node.warn(`Rayvn /files returned ${res.status} for ${file.name}`);
            failed.push({ name: file.name || "unknown file", reason: "rayvn_rejected" });
        }
    } catch (e) {
        node.warn(`Error uploading ${file.name}: ${e.message}`);
        failed.push({ name: file.name || "unknown file", reason: e.message });
    }
}

// Replace binary file objects with the Rayvn file IDs
// Rayvn expects only IDs in the log entry payload, not the raw binaries
msg.payload.files = resolved;

// Append a notice to the log entry text so the Rayvn recipient knows
// that some attachments were not delivered
if (failed.length > 0) {
    const notice = " [" + failed.length + "/" + (resolved.length + failed.length) + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";
    msg.payload.text = (msg.payload.text || "") + notice;
}

// Pass failed files to the next node (Check for failed uploads)
// which builds a notification back to the original sender
if (msg.entry) {
    msg.entry._failed_files = failed;
}

return msg;

const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.log_id) {
    node.error("Rayvn not configured on this connection");
    return null;
}

msg.url = global.get("parat_bridge").base_urls.rayvn
    + "/logs/" + target.client_specific.log_id + "/entry";

msg.headers = {
    "Authorization": "Bearer " + target.api_key,
    "Content-Type":  "application/json",
    "Accept":        "application/json"
};

return msg;

msg.topic = "response"

if (msg.statusCode == 200) {
    msg.result = true
} else {
    msg.result = false
}

return msg;

/**
 * Build notification if any files failed during Rayvn upload.
 * Pre-known failures (oversized, non_transferable) are handled
 * upstream in POST entries before the switch node.
 *
 * Output 1: msg continues (always)
 * Output 2: notification payload (only on upload failures)
 */
const entry  = msg.entry;
const failed = (entry && entry._failed_files) || [];

if (failed.length === 0) return [msg, null];

const succeeded = Array.isArray(msg.payload.files)
    ? msg.payload.files.length : 0;

const notification = {
    payload: {
        type:         "upload_failed",
        entry_id:     entry.id,
        file_names:   failed.map(f => f.name),
        file_count:   failed.length,
        total_files:  succeeded + failed.length,
        succeeded,
        entry_author: entry.author,
        metadata:     msg.metadata
    }
};

return [msg, notification];
